{
  "id": "function-compute-on-run",
  "title": "Function node: custom JavaScript with discovered ports",
  "description": "The Function node (JavaScriptFunction) runs the JavaScript in `functionScript`. Its data ports do not exist until the script mentions them: reading `Inputs.x` creates an input named x, assigning `Outputs.y = …` creates an output named y, and calling `Outputs.done()` fires a signal output — this is why the catalog marks them runtime-determined. The script runs when `run` is triggered (or when connected inputs change, if `run` is unconnected). Here a button converts a text amount to a formatted price.",
  "demonstrates": [
    "JavaScriptFunction",
    "Text",
    "net.noodl.controls.textinput"
  ],
  "components": [
    {
      "name": "/Price Preview",
      "nodes": [
        {
          "id": "root",
          "type": "Group",
          "label": "Layout",
          "parameters": {
            "flexDirection": "column"
          },
          "children": [
            "amount_input",
            "format_button",
            "price_text"
          ]
        },
        {
          "id": "amount_input",
          "type": "net.noodl.controls.textinput",
          "label": "Amount",
          "parent": "root",
          "parameters": {
            "placeholder": "0.00"
          }
        },
        {
          "id": "format_button",
          "type": "net.noodl.controls.button",
          "label": "Format",
          "parent": "root",
          "parameters": {
            "label": "Format price"
          }
        },
        {
          "id": "price_text",
          "type": "Text",
          "label": "Formatted price",
          "parent": "root"
        },
        {
          "id": "format_price",
          "type": "JavaScriptFunction",
          "label": "Format as EUR",
          "parameters": {
            "functionScript": "const amount = Number(Inputs.amount) || 0;\nOutputs.formatted = new Intl.NumberFormat('de-DE', { style: 'currency', currency: 'EUR' }).format(amount);\nOutputs.done();"
          }
        }
      ],
      "connections": [
        {
          "fromId": "amount_input",
          "fromProperty": "onTextChanged",
          "toId": "format_price",
          "toProperty": "amount"
        },
        {
          "fromId": "format_button",
          "fromProperty": "onClick",
          "toId": "format_price",
          "toProperty": "run"
        },
        {
          "fromId": "format_price",
          "fromProperty": "formatted",
          "toId": "price_text",
          "toProperty": "text"
        }
      ]
    }
  ]
}

